contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g1, bytes32 g2, uint amount1, uint amount2) public payable {
        require(address(this).balance >= amount1);
        uint bal0 = address(c).balance;
        bool r1;
        c.lockInGuess{value: amount1}(g1);
        r1 = false;
        uint bal1 = address(c).balance;
        require(address(this).balance >= amount2);
        bool r2;
        try c.lockInGuess{value: amount2}(g2) { r2 = false; } catch { r2 = true; }
        if (r1) {
            assert(r2 && bal1 == bal0 && address(c).balance == bal0);
        } else {
            assert(r2 && bal1 == bal0 + amount1 && address(c).balance == bal1);
        }
    }
    receive() external payable {}
}

