contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 hash, uint badValue) public payable {
        require(badValue != 1 ether);
        require(address(this).balance >= 3 ether);

        // first lock with correct value
        c.lockInGuess{value: 1 ether}(hash);

        // settle in the same block: must revert (target block not reached)
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        uint balAfterFailedSettle = address(c).balance;

        // settle() in the same block must not have reset the guess:
        // relocking with a wrong value must revert...
        bool relockBadReverted;
        try c.lockInGuess{value: badValue}(hash) { relockBadReverted = false; } catch { relockBadReverted = true; }

        // ...and relocking with exactly 1 ether must also revert (still locked)
        bool relockGoodReverted;
        try c.lockInGuess{value: 1 ether}(bytes32(uint256(1))) { relockGoodReverted = false; } catch { relockGoodReverted = true; }

        assert(settleReverted && relockBadReverted && relockGoodReverted && balAfterFailedSettle == 1 ether);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 * amount);
        // first lock: must succeed (fresh state)
        c.lockInGuess{value: amount}(bytes32(uint(1)));
        // settle before target block: must revert
        bool earlyReverted;
        try c.settle() { earlyReverted = false; } catch { earlyReverted = true; }
        // mine one extra block via a state-changing call on c: re-lock should revert (slot taken)
        bool relockReverted;
        try c.lockInGuess{value: amount}(bytes32(uint(2))) { relockReverted = false; } catch { relockReverted = true; }
        // advance past target block: lockInGuess again to push block.number, then settle
        c.lockInGuess(bytes32(uint(3)));
        // settle must now succeed (block.number > guesses.block for first lock, since second lock bumped it further)
        bool settled;
        try c.settle() { settled = true; } catch { settled = false; }
        // settle again must revert (slot cleared)
        bool secondSettleReverted;
        try c.settle() { secondSettleReverted = false; } catch { secondSettleReverted = true; }
        // slot cleared: lockInGuess must succeed now
        bool relockOk;
        try c.lockInGuess{value: amount}(bytes32(uint(4))) { relockOk = true; } catch { relockOk = false; }
        assert(earlyReverted && relockReverted && settled && secondSettleReverted && relockOk);
    }
    receive() external payable {}
}

